def get_by_ids(user_ids: list[int]) -> list[dict]:
    """Return users with any of the given ids, ordered by id, each at most once."""
    users = []
    seen = set()
    for user_id in sorted(user_ids):
        if user_id in seen:
            continue
        seen.add(user_id)
        user = get_by_id(user_id)
        if user is not None:
            users.append(user)
    return users


